use anyhow::{Result,ensure};use glam::{Mat4,Vec3,Quat};
use std::{sync::{Arc,atomic::{AtomicBool,Ordering}},time::{Duration,Instant},thread};
use windows::Win32::Graphics::{Direct3D11::ID3D11Texture2D,Dxgi::*,Dxgi::Common::*};
use crate::{gpu::{Gpu,Target},scene::Scene,hud_stream::HudStream,profile::{self,Profile},perf::{Metrics,GpuTimer},window::Window,log::{Log,root}};
pub fn run(log:&Log,args:&[String])->Result<()>{
 let value=|flag:&str|args.iter().position(|a|a==flag).and_then(|i|args.get(i+1)).and_then(|s|s.parse::<f64>().ok());
 let no_hud=args.iter().any(|a|a=="--no-hud");let duration=value("--seconds");let soak=value("--soak-seconds");let validate=args.iter().any(|a|a=="--validate");let pair=args.iter().any(|a|a=="--headset-pair");let sync=args.iter().any(|a|a=="--sync-hud");let label=args.iter().position(|a|a=="--perf-label").and_then(|i|args.get(i+1));if let Some(label)=label{ensure!(!label.is_empty()&&label.chars().all(|c|c.is_ascii_alphanumeric()||c=='_'),"진단 이름은 영문/숫자/밑줄만");}
 let profiling=label.is_some()||pair;let stop=Arc::new(AtomicBool::new(false));let s=stop.clone();ctrlc::set_handler(move||s.store(true,Ordering::SeqCst))?;
 let mut window=Window::new(validate||soak.is_some()||pair)?;let load_start=Instant::now();let receiver=crate::load_async(args.iter().any(|a|a=="--generated-textures"));let mut gpu=Gpu::new(log,None,0xb000)?;
 let factory:IDXGIFactory2=unsafe{CreateDXGIFactory1()?};let(w,h)=window.size();let desc=DXGI_SWAP_CHAIN_DESC1{Width:w,Height:h,Format:DXGI_FORMAT_R8G8B8A8_UNORM,SampleDesc:DXGI_SAMPLE_DESC{Count:1,Quality:0},BufferUsage:DXGI_USAGE_RENDER_TARGET_OUTPUT,BufferCount:2,Scaling:DXGI_SCALING_STRETCH,SwapEffect:DXGI_SWAP_EFFECT_FLIP_DISCARD,AlphaMode:DXGI_ALPHA_MODE_IGNORE,..Default::default()};let swapchain=unsafe{factory.CreateSwapChainForHwnd(&gpu.device,window.hwnd,&desc,None,None)?};unsafe{factory.MakeWindowAssociation(window.hwnd,DXGI_MWA_NO_ALT_ENTER)?;}
 let make_target=|gpu:&Gpu,w,h|->Result<Target>{let texture:ID3D11Texture2D=unsafe{swapchain.GetBuffer(0)?};gpu.target(&texture,w,h,DXGI_FORMAT_R8G8B8A8_UNORM_SRGB)};let mut target=Some(make_target(&gpu,w,h)?);
 let prepared=loop{if !window.poll()||stop.load(Ordering::SeqCst){return Ok(());}match receiver.try_recv(){Ok(result)=>break result?,Err(std::sync::mpsc::TryRecvError::Empty)=>{},Err(e)=>return Err(e.into())}thread::sleep(Duration::from_millis(10));};let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;let prepare_ms=profile::ms(load_start);
 scene.hud_scale=if pair{1.0}else{0.55};scene.playing=soak.is_some()&&!args.iter().any(|a|a=="--paused");scene.projectiles_enabled=!args.iter().any(|a|a=="--no-projectiles");if pair{scene.table_origin.z=-1.4;}
 let pair_target=if pair{let [w,h]=gpu.settings.eye_size([1632,1760],[3264,3520]);Some(gpu.offscreen(w,h)?.1)}else{None};
 let mut hud=HudStream::new(&scene.assets.portraits,sync)?;let mut last_hud=Instant::now()-Duration::from_secs(1);let mut timers=[GpuTimer::new(&gpu.device)?,GpuTimer::new(&gpu.device)?];let mut metrics=Metrics::new();let mut phases=Profile::new();let start=Instant::now();let mut previous=start;let mut next_frame=start;let(mut az,mut elevation,mut distance)=(0.0f32,42f32.to_radians(),3.7f32);let(mut resized,mut toggled)=(false,false);let mut resize_count=0u32;let mut over_budget=0u64;
 log.line(format!("일반 화면 준비 · 진단={label:?} headsetPair={pair} syncHUD={sync} scale={} MSAA={} projectiles={} 준비={prepare_ms:.3}ms",gpu.settings.render_scale,gpu.settings.msaa_samples,scene.projectiles_enabled));
 while window.poll()&&!stop.load(Ordering::SeqCst){
  let frame_start=Instant::now();let mut phase=profile::Frame::default();let dt=previous.elapsed().as_secs_f32().min(0.1);previous=Instant::now();if duration.or(soak).is_some_and(|s|start.elapsed().as_secs_f64()>=s){break;}
  let t=Instant::now();let a=window.actions();az=(az-a.orbit_x).clamp(-1.52,1.52);elevation=(elevation+a.orbit_y).clamp(0.12,1.56);distance=(distance*0.9f32.powf(a.wheel)).clamp(1.2,12.0);if a.toggle{scene.toggle();}if a.back{scene.seek(scene.time-600.0);}if a.forward{scene.seek(scene.time+600.0);}if a.speed{scene.cycle_speed();}if a.recenter{az=0.0;elevation=42f32.to_radians();distance=3.7;}scene.table_height=(scene.table_height+a.height).clamp(0.3,1.5);scene.table_scale=(scene.table_scale+a.scale).clamp(0.5,3.0);if a.height!=0.0||a.scale!=0.0{scene.notify_adjustment();}phase.values[14]=profile::ms(t);
  if validate&&!toggled&&start.elapsed()>Duration::from_secs(1){scene.toggle();scene.seek(scene.time+600.0);scene.table_scale=1.2;toggled=true;}
  if validate&&!resized&&start.elapsed()>Duration::from_secs(2){unsafe{let _=windows::Win32::UI::WindowsAndMessaging::ShowWindow(window.hwnd,windows::Win32::UI::WindowsAndMessaging::SW_SHOWNOACTIVATE);let _=windows::Win32::UI::WindowsAndMessaging::SetWindowPos(window.hwnd,Some(windows::Win32::UI::WindowsAndMessaging::HWND_BOTTOM),0,0,1100,760,windows::Win32::UI::WindowsAndMessaging::SWP_NOMOVE|windows::Win32::UI::WindowsAndMessaging::SWP_NOACTIVATE);}resized=true;}
  if window.resized(){let(w,h)=window.size();target.take();unsafe{gpu.context.ClearState();swapchain.ResizeBuffers(0,w,h,DXGI_FORMAT_UNKNOWN,DXGI_SWAP_CHAIN_FLAG(0))?;}target=Some(make_target(&gpu,w,h)?);resize_count+=1;log.line(format!("D3D11 리사이즈 {w}x{h}"));}
  let target=pair_target.as_ref().unwrap_or_else(||target.as_ref().unwrap());let center=Vec3::new(scene.table_origin.x,scene.table_height,scene.table_origin.z);let head=if pair{Vec3::new(0.0,1.1,0.0)}else{center+Vec3::new(az.sin()*elevation.cos(),elevation.sin(),az.cos()*elevation.cos())*distance};let view=Mat4::look_at_rh(head,center,Vec3::Y);let rotation=view.inverse().to_scale_rotation_translation().1;scene.show_hud=!no_hud&&hud.ready();scene.update(&mut gpu,head,rotation,dt)?;phase.scene(&scene);
  let request=if !no_hud&&scene.hud_dirty&&last_hud.elapsed().as_secs_f32()>=0.1{scene.hud_dirty=false;last_hud=Instant::now();Some(scene.hud_content())}else{None};phase.hud(hud.update(&gpu,request)?);
  let t=Instant::now();let mut gpu_ms=Some(0.0);for eye in 0..if pair{2}else{1}{let measured=timers[eye].begin(&gpu.context)?;gpu_ms=gpu_ms.zip(measured).map(|(a,b)|a+b);let vp=if pair{headset_projection(head,rotation,eye)}else{Mat4::perspective_rh(42f32.to_radians(),target.width as f32/target.height as f32,0.01,40.0)*view};gpu.render(target,vp,scene.world(),true);timers[eye].end(&gpu.context);if pair{unsafe{gpu.context.Flush();}}}phase.values[11]=profile::ms(t);
  let cpu_ms=profile::ms(frame_start);phase.values[19]=cpu_ms;if cpu_ms>1000.0/120.0{over_budget+=1;}metrics.frame(cpu_ms,gpu_ms);if profiling{phases.frame(phase);}unsafe{swapchain.Present(0,DXGI_PRESENT(0)).ok()?;}
  if metrics.report(log,gpu.calls*if pair{2}else{1},scene.time,scene.visible).is_some(){gpu.check()?;if profiling{phases.report(log,&scene,&gpu,start.elapsed().as_secs_f64());}}
  next_frame+=Duration::from_secs_f64(1.0/120.0);let now=Instant::now();if now<next_frame{thread::sleep(next_frame-now);}else if now.duration_since(next_frame)>Duration::from_secs_f64(1.0/120.0){next_frame=now;}
 }
 if profiling{phases.report(log,&scene,&gpu,start.elapsed().as_secs_f64());}let samples=&metrics.samples;let warm:Vec<_>=samples.iter().filter(|s|s.elapsed_seconds>=30.0).collect();let increase=warm.last().zip(warm.first()).map(|(a,b)|a.private_bytes as i64-b.private_bytes as i64);
 let report=serde_json::json!({"검증":"일반 창 실행 완료","frames":metrics.frames,"elapsed":start.elapsed().as_secs_f64(),"resizeValidated":resized&&resize_count>0,"resizeCount":resize_count,"controlsValidated":toggled,"samples":samples,"warmPrivateIncreaseBytes":increase,"snapshot":scene.snapshot(),"실기기":"세션 미실행","profile":phases.reports,"pair":pair,"syncHud":sync,"projectiles":scene.projectiles_enabled,"renderScale":gpu.settings.render_scale,"MSAA":gpu.settings.msaa_samples,"renderSize":[pair_target.as_ref().map(|t|t.width),pair_target.as_ref().map(|t|t.height)],"gpuScope":"각 눈 draw+resolve만 · CPU 준비/이미지대기 제외","cpuOver8_33ms":over_budget,"prepareMs":prepare_ms,"atlasUploads":gpu.atlas_uploads.get(),"sizes":scene.runtime_sizes()});let file=if let Some(label)=label{format!("native_perf_{label}.json")}else if soak.is_some(){"native_viewer_soak.json".into()}else{"native_viewer_desktop.json".into()};std::fs::write(root().join("_tmp/logs").join(&file),serde_json::to_vec_pretty(&report)?)?;log.line(format!("일반 화면 종료 · frames={} · 기록={file}",metrics.frames));Ok(())
}
fn headset_projection(head:Vec3,q:Quat,eye:usize)->Mat4{let x=if eye==0{-0.032}else{0.032};let p=head+q*Vec3::new(x,0.0,0.0);let fov=if eye==0{openxr::Fovf{angle_left:-0.94247776,angle_right:0.6981317,angle_up:0.7679449,angle_down:-0.9599311}}else{openxr::Fovf{angle_left:-0.6981317,angle_right:0.94247776,angle_up:0.7679449,angle_down:-0.9599311}};crate::xrflow::projection(&openxr::View{pose:openxr::Posef{position:openxr::Vector3f{x:p.x,y:p.y,z:p.z},orientation:openxr::Quaternionf{x:q.x,y:q.y,z:q.z,w:q.w}},fov})}
